-- =====================================================================
-- 0080 — 8D Problem Solving (a new KMR App, for any company: each company sees only its own data)
--  • One 8D report per problem: D0 symptom and emergency response, D1 team, D2 problem description (5W2H), D3 interim containment,
--    D4 root causes (occurrence, escape, system), D5 permanent corrective actions, D6 implementation and validation,
--    D7 prevention of recurrence, D8 closure and team recognition. A step is ticked only when its content is there.
--  • Root-cause tools: Is / Is-not table, 5-Why chains and a cause-and-effect (fishbone) sheet.
--  • Actions with owner, due date, evidence and effectiveness check; overdue list across all 8Ds.
--  • Numbered reports (8D/26-27/0001), activity log, dashboard, printed 8D report with the customer logo,
--    unique reference number and format revision on every page.
--  • Sample data to validate the flow and delete again.
-- Needs 0079. Safe to re-run. Generated by scripts/make-d8.py.
-- =====================================================================
do $$ begin
  if to_regprocedure('console.crm_sample(uuid, text)') is null then raise exception 'Run 0079_crm_rfq.sql first.'; end if;
end $$;

insert into console.products (code, name, description, app_path, seat_label, current_version, sort_order) values
  ('d8', '8D Problem Solving', 'Customer complaints and internal problems solved step by step, D0 to D8: team, containment, root causes, corrective actions, prevention and a printed 8D report', '/it/d8.html', 'users', '1.0.0', 15)
on conflict (code) do nothing;
insert into console.releases (product_code, version, notes) values
  ('d8', '1.0.0', '8D Problem Solving: D0 to D8 workflow, team, 5W2H, containment, root causes, actions, prevention, closure, root-cause tools, dashboard, printed 8D report') on conflict do nothing;
insert into console.prices (product_code, period, currency, unit_amount, min_seats, active, note)
select v.code, v.period, 'INR', v.amt, 3, true, 'Starting price list (0080) — per user, change in Console › Billing'
  from (values ('d8', 'month', 80), ('d8', 'year', 800)) v(code, period, amt)
 where not exists (select 1 from console.prices x where x.product_code = v.code and x.currency = 'INR' and x.period = v.period)
on conflict (product_code, period, currency) do nothing;
insert into public.app_listings (code, name, tagline, features, sort_order, is_active) values
