delete from console.app_features f where f.product_code = 'd8' and f.name = 'Core platform' and not exists (select 1 from console.invoice_lines il where il.feature_id = f.id);
update console.app_features set price_year = price_month * 10 where product_code = 'd8' and price_year = 0;
