-- ---------- tables (every table holds one company's rows only: customer_id) ----------
create table if not exists console.d8_counters (
  customer_id uuid not null references console.customers(id) on delete cascade, key text not null, n bigint not null default 0, sample boolean not null default false, primary key (customer_id, key));
create table if not exists console.d8_settings (
  customer_id uuid primary key references console.customers(id) on delete cascade, data jsonb not null default '{}', sample boolean not null default false, updated_at timestamptz not null default now());
create table if not exists console.d8_reports (
  id uuid primary key default gen_random_uuid(), customer_id uuid not null references console.customers(id) on delete cascade,
  no text not null, title text not null, status text not null default 'open' check (status in ('open', 'closed')),
  source text not null default 'Customer complaint' check (source in ('Customer complaint', 'Internal rejection', 'Supplier problem', 'Audit finding', 'Field failure', 'Other')),
  complainant text, complaint_ref text, part_no text, part_name text, lot_no text, qty_affected numeric(14,3) check (qty_affected is null or qty_affected >= 0),
  severity text not null default 'Major' check (severity in ('Minor', 'Major', 'Critical')), opened_on date not null default current_date, due_on date, owner text,
  sections jsonb not null default '{}', analysis jsonb not null default '{}', steps jsonb not null default '{}', closed_on date, closed_by text, notes text,
  sample boolean not null default false, created_by text, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), unique (customer_id, no));
create index if not exists d8_reports_status on console.d8_reports (customer_id, status, due_on);
create table if not exists console.d8_actions (
  id uuid primary key default gen_random_uuid(), customer_id uuid not null references console.customers(id) on delete cascade,
  report_id uuid not null references console.d8_reports(id) on delete cascade, kind text not null default 'ICA' check (kind in ('ICA', 'PCA', 'PREVENT')),
  seq int not null default 1, text text not null, owner text, due_on date, status text not null default 'open' check (status in ('open', 'done')), done_on date, evidence text,
  verified boolean not null default false, verified_on date, sample boolean not null default false, created_by text, created_at timestamptz not null default now());
create index if not exists d8_actions_report on console.d8_actions (report_id);
create index if not exists d8_actions_open on console.d8_actions (customer_id, status, due_on);
create table if not exists console.d8_log (
  id uuid primary key default gen_random_uuid(), customer_id uuid not null references console.customers(id) on delete cascade,
  report_id uuid not null references console.d8_reports(id) on delete cascade, at timestamptz not null default now(), by text, text text not null, sample boolean not null default false);
create index if not exists d8_log_report on console.d8_log (report_id, at);
do $$ declare t text; begin foreach t in array array['d8_counters','d8_settings','d8_reports','d8_actions','d8_log'] loop
  execute format('alter table console.%I enable row level security', t);
  execute format('drop policy if exists %I on console.%I', t || '_staff', t);
  execute format('create policy %I on console.%I for all to authenticated using (console.is_staff()) with check (console.is_staff())', t || '_staff', t);
end loop; end $$;

